effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

    vec4 Desaturate(vec3 color, float Desaturation)
    {
    vec3 grayXfer = vec3(0.3, 0.59, 0.11);
    vec3 gray = vec3(dot(grayXfer, color));
    return vec4(mix(color, gray, Desaturation), 1.0);
    }

    vec3 RGBToHSL(vec3 color)
    {
    vec3 hsl;
    float fmin = min(min(color.r, color.g), color.b);
    float fmax = max(max(color.r, color.g), color.b);
    float delta = fmax - fmin;
    hsl.z = (fmax + fmin) / 2.0;

    if (delta == 0.0)
    {
    hsl.x = 0.0;
    hsl.y = 0.0;
    }
    else
    {
    if (hsl.z < 0.5)
    hsl.y = delta / (fmax + fmin);
    else
    hsl.y = delta / (2.0 - fmax - fmin);
    float deltaR = (((fmax - color.r) / 6.0) + (delta / 2.0)) / delta;
    float deltaG = (((fmax - color.g) / 6.0) + (delta / 2.0)) / delta;
    float deltaB = (((fmax - color.b) / 6.0) + (delta / 2.0)) / delta;
    if (color.r == fmax )
    hsl.x = deltaB - deltaG;
    else if (color.g == fmax)
    hsl.x = (1.0 / 3.0) + deltaR - deltaB;
    else if (color.b == fmax)
    hsl.x = (2.0 / 3.0) + deltaG - deltaR;

    if (hsl.x < 0.0)
    hsl.x += 1.0;
    else if (hsl.x > 1.0)
    hsl.x -= 1.0;
    }

    return hsl;
    }

    float HueToRGB(float f1, float f2, float hue)
    {
    if (hue < 0.0)
    hue += 1.0;
    else if (hue > 1.0)
    hue -= 1.0;
    float res;
    if ((6.0 * hue) < 1.0)
    res = f1 + (f2 - f1) * 6.0 * hue;
    else if ((2.0 * hue) < 1.0)
    res = f2;
    else if ((3.0 * hue) < 2.0)
    res = f1 + (f2 - f1) * ((2.0 / 3.0) - hue) * 6.0;
    else
    res = f1;
    return res;
    }

    vec3 HSLToRGB(vec3 hsl)
    {
    vec3 rgb;
    if (hsl.y == 0.0)
    rgb = vec3(hsl.z);
    else
    {
    float f2;
    if (hsl.z < 0.5)
    f2 = hsl.z * (1.0 + hsl.y);
    else
    f2 = (hsl.z + hsl.y) - (hsl.y * hsl.z);
    float f1 = 2.0 * hsl.z - f2;
    rgb.r = HueToRGB(f1, f2, hsl.x + (1.0/3.0));
    rgb.g = HueToRGB(f1, f2, hsl.x);
    rgb.b= HueToRGB(f1, f2, hsl.x - (1.0/3.0));
    }

    return rgb;
    }

    vec3 ContrastSaturationBrightness(vec3 color, float brt, float sat, float con)
    {
    const float AvgLumR = 0.5;
    const float AvgLumG = 0.5;
    const float AvgLumB = 0.5;

    const vec3 LumCoeff = vec3(0.2125, 0.7154, 0.0721);

    vec3 AvgLumin = vec3(AvgLumR, AvgLumG, AvgLumB);
    vec3 brtColor = color * brt;
    vec3 intensity = vec3(dot(brtColor, LumCoeff));
    vec3 satColor = mix(intensity, brtColor, sat);
    vec3 conColor = mix(AvgLumin, satColor, con);
    return conColor;
    }

    vec3 BlendHue(vec3 base, vec3 blend)
    {
    vec3 baseHSL = RGBToHSL(base);
    return HSLToRGB(vec3(RGBToHSL(blend).r, baseHSL.g, baseHSL.b));
    }

    vec3 BlendSaturation(vec3 base, vec3 blend)
    {
    vec3 baseHSL = RGBToHSL(base);
    return HSLToRGB(vec3(baseHSL.r, RGBToHSL(blend).g, baseHSL.b));
    }

    vec3 BlendColor(vec3 base, vec3 blend)
    {
    vec3 blendHSL = RGBToHSL(blend);
    return HSLToRGB(vec3(blendHSL.r, blendHSL.g, RGBToHSL(base).b));
    }

    vec3 BlendLuminosity(vec3 base, vec3 blend)
    {
    vec3 baseHSL = RGBToHSL(base);
    return HSLToRGB(vec3(baseHSL.r, baseHSL.g, RGBToHSL(blend).b));
    }

    float hash(float x){
          return fract(sin(x*133.3)*13.13);
    }

    #define PI 3.14159265359

    // alternate the direction of rotation along a checker pattern
    #define CHECKERED


    mat2 rot(float angle) {
        return mat2(cos(angle), -sin(angle),
                    sin(angle), cos(angle));
    }

    float checkersign(vec2 uv) {
    #ifdef CHECKERED
        uv = floor(uv);
        return sign(mod(uv.x + uv.y, 2.) - .5);
    #else
        return 1.;
    #endif
    }



    vec3 mod289(vec3 x) {
      return x - floor(x * (1.0 / 289.0)) * 289.0;
    }

    vec4 mod289(vec4 x) {
      return x - floor(x * (1.0 / 289.0)) * 289.0;
    }

    vec4 permute(vec4 x) {
         return mod289(((x*34.0)+1.0)*x);
    }

    vec4 taylorInvSqrt(vec4 r)
    {
      return 1.79284291400159 - 0.85373472095314 * r;
    }


    float snoise(vec3 v, out vec3 gradient, float time)
    {
      const vec2  C = vec2(1.0/6.0, 1.0/3.0) ;
      const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);

    // First corner
      vec3 i  = floor(v + dot(v, C.yyy) );
      vec3 x0 =   v - i + dot(i, C.xxx) ;

    // Other corners
      vec3 g = step(x0.yzx, x0.xyz);
      vec3 l = 1.0 - g;
      vec3 i1 = min( g.xyz, l.zxy );
      vec3 i2 = max( g.xyz, l.zxy );

      //   x0 = x0 - 0.0 + 0.0 * C.xxx;
      //   x1 = x0 - i1  + 1.0 * C.xxx;
      //   x2 = x0 - i2  + 2.0 * C.xxx;
      //   x3 = x0 - 1.0 + 3.0 * C.xxx;
      vec3 x1 = x0 - i1 + C.xxx;
      vec3 x2 = x0 - i2 + C.yyy; // 2.0*C.x = 1/3 = C.y
      vec3 x3 = x0 - D.yyy;      // -1.0+3.0*C.x = -0.5 = -D.y

    // Permutations
      i = mod289(i); 
      vec4 p = permute( permute( permute( 
                 i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
               + i.y + vec4(0.0, i1.y, i2.y, 1.0 )) 
               + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));

    // Gradients: 7x7 points over a square, mapped onto an octahedron.
    // The ring size 17*17 = 289 is close to a multiple of 49 (49*6 = 294)
      float n_ = 0.142857142857; // 1.0/7.0
      vec3  ns = n_ * D.wyz - D.xzx;

      vec4 j = p - 49.0 * floor(p * ns.z * ns.z);  //  mod(p,7*7)

      vec4 x_ = floor(j * ns.z);
      vec4 y_ = floor(j - 7.0 * x_ );    // mod(j,N)

      vec4 x = x_ *ns.x + ns.yyyy;
      vec4 y = y_ *ns.x + ns.yyyy;
      vec4 h = 1.0 - abs(x) - abs(y);

      vec4 b0 = vec4( x.xy, y.xy );
      vec4 b1 = vec4( x.zw, y.zw );

      //vec4 s0 = vec4(lessThan(b0,0.0))*2.0 - 1.0;
      //vec4 s1 = vec4(lessThan(b1,0.0))*2.0 - 1.0;
      vec4 s0 = floor(b0)*2.0 + 1.0;
      vec4 s1 = floor(b1)*2.0 + 1.0;
      vec4 sh = -step(h, vec4(0.0));

      vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
      vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;

      vec3 p0 = vec3(a0.xy,h.x);
      vec3 p1 = vec3(a0.zw,h.y);
      vec3 p2 = vec3(a1.xy,h.z);
      vec3 p3 = vec3(a1.zw,h.w);

    //Normalise gradients
      vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
      p0 *= norm.x;
      p1 *= norm.y;
      p2 *= norm.z;
      p3 *= norm.w;

    // add rotation
      x0.xy *= rot(time*checkersign(a0.xy));
      x1.xy *= rot(time*checkersign(a0.zw));
      x2.xy *= rot(time*checkersign(a1.xy));
      x3.xy *= rot(time*checkersign(a1.zw));

    // Mix final noise value
      vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
      vec4 m2 = m * m;
      vec4 m4 = m2 * m2;
      vec4 pdotx = vec4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3));

    // Determine noise gradient
      vec4 temp = m2 * m * pdotx;
      gradient = -8.0 * (temp.x * x0 + temp.y * x1 + temp.z * x2 + temp.w * x3);
      gradient += m4.x * p0 + m4.y * p1 + m4.z * p2 + m4.w * p3;
      gradient *= 42.0;

      return 42.0 * dot(m4, pdotx);
    }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;
        vec2 image_size = getTexSize(inputImg.size);
        float maxF = max(acScreenSize.x, acScreenSize.y);
        vec2 texelSize = 1.0 / vec2(maxF, maxF);

        vec2 TanRyu;
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;

        TanRyu /= scale;
        TanRyu *= rot2m((0.0)*0.0174533);
        TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;

        vec2 scaleVec;
        scaleVec = vec2(scale*stretch.x,scale*stretch.y);
        TanRyu /= scaleVec;

        /////////////////////////

         vec4 fragColor;

         float time = autop? (EVO*0.5)+(acTime*0.01) * 12.0 : EVO*0.5;
         vec2 resolution = vec2(acScreenSize.x, acScreenSize.y);
         vec2 uv = TanRyu;
         vec2 uv2 = uv;
         uv += vec2(0.5);
         uv.x = uv.x * acScreenSize.x / acScreenSize.y;

         float a= kangle * 3.1415926 / 180.0;
         float si=sin(a),co=cos(a);
         uv*=mat2(co,-si,si,co);
         uv*=length(uv+vec2(0.0,8.0))*.5+1.;

         uv -= vec2(0.5);

         vec3 c=kcolor.rgb;
         float v=1.-sin(hash(floor(uv.x*100.))*2.);
         float b=clamp(abs(sin(20.*time*v+uv.y*(5./(3.+klength +v))))-.95,0.,1.)*10. * kalpha;

         c*=v*b ; 

         vec4 albedo = texture2DCv(inputImg.texture,uv2);
         fragColor = vec4(c, 1.0);
         // fragColor = albedo;

    	vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
            // resultfinal = (newLayer(texColor, factor) * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor, resultfinal, alpha);
    	// }
    }
